def solve(g,bg=5):
    g=np.array(g); H,W=g.shape; out=g.copy()
    # decompose: repeatedly place L-tromino patterns within connected same-color comps
    def place_and_paint(o,v,minr,maxr,minc,maxc):
        for mr in range(minr,maxr+1):
            for mc in range(minc,maxc+1):
                if maxr-minr==1 and maxc-minc==1:
                    full={(i,j) for i in (mr,mr+1) for j in (mc,mc+1)}
                    miss=full-set(o)
                    if len(miss)==1:
                        m=list(miss)[0]
                        cr=sum(rs)/len(o); cc=sum(csj)/len(o)
                        dr=(1 if m[0]>cr else (-1 if m[0]<cr else 0))
                        dc=(1 if m[1]>cc else (-1 if m[1]<cc else 0))
                        r,c=m[0]+dr,m[1]+dc
                        while 0<=r<H and 0<=c<W and g[r,c]==bg:
                            out[r,c]=v; r+=dr; c+=dc
    for v,o in comps(g,bg):
        rs=[i for i,j in o]; csj=[j for i,j in o]
        minr,maxr=min(rs),max(rs); minc,maxc=min(csj),max(csj)
